insert into kb_procedures (id, name, jurisdiction, authority, eligibility, channel, cost, timing, legal_basis, source_ids, verification_status, notes, verified_at) values
  ('P-CPF', 'Inscrição no CPF (pessoa estrangeira)', 'Federal', 'Receita Federal', 'Pessoas físicas brasileiras e estrangeiras, residentes e não residentes no Brasil', 'Online (formulário ''Inscrever Estrangeiro no CPF''); e-mail; unidades da Receita; conveniados (Correios, Banco do Brasil, Caixa, cartórios)', 'Gratuito na Receita; R$ 7,00 nos conveniados', 'Cerca de 15 min presencial; cerca de 48 h por e-mail', 'A confirmar (instrução normativa da Receita)', array['S01']::text[], 'Confirmado', 'CPF é cadastro fiscal: não comprova situação migratória. A página não diz se os conveniados atendem estrangeiros — a confirmar. Regra do app: se a pessoa responde Não ou Não sei à pergunta "Você já tem CPF?", este fluxo entra no caminho automaticamente como etapa 1.', '28/10/2026'),
  ('P-RES-VEN', 'Autorização de residência – Venezuela, Guiana e Suriname (código 273; prazo indeterminado: código 299)', 'Federal', 'Polícia Federal', 'Nacionais da Venezuela, Guiana ou Suriname. Crianças e incapazes: pedido por um dos pais ou representante legal', 'Formulário eletrônico no site da PF + atendimento presencial em unidade da PF (agendar em S20)', 'R$ 168,13 + R$ 204,77 quando aplicáveis; isenção por declaração de hipossuficiência', 'Temporária: 2 anos (S15 – confirmar na PF). Prazo indeterminado: pedir nos 90 dias antes do vencimento (S15)', 'Portaria Interministerial MJSP/MRE nº 19/2021; Decreto nº 9.199/2017', array['S10','S15','S08']::text[], 'Confirmado (documentos); validade a confirmar na PF', 'Divergência entre fontes oficiais: a página do MJSP (S04) ainda cita as Portarias 9/2018 e 15/2018 e pede foto 3x4. Seguimos a PF (S10), que cita a Portaria 19/2021 e só pede foto se a biometria falhar.', '28/10/2026'),
  ('P-RES-MERCOSUL', 'Autorização de residência – Acordo sobre Residência do Mercosul', 'Federal', 'Polícia Federal', 'Nacionais de Argentina, Bolívia, Chile, Colômbia, Equador, Paraguai, Peru e Uruguai (S09)', 'Formulário eletrônico no site da PF + atendimento presencial (S03)', 'R$ 168,13 + R$ 204,77 quando aplicáveis (S03, S16); isenção por hipossuficiência (S08)', 'Temporária: até 2 anos. Permanente: pedir 90 dias antes do vencimento (Decreto 6.975, arts. 4 e 5)', 'Decreto nº 6.975/2009 (Argentina, Bolívia, Chile, Paraguai, Uruguai). Adesão de Colômbia, Equador e Peru por outro ato: a confirmar', array['S13','S16','S09']::text[], 'Parcial: norma confirmada; página da PF restrita; lista operacional a confirmar', 'A página da PF (S11) exigia login em 28/10/2026. Lista operacional vem de guia universitário (S16).', '28/10/2026'),
  ('P-RES-REUNIAO', 'Autorização de residência – Reunião familiar com brasileiro ou imigrante com autorização de residência', 'Federal', 'Polícia Federal', 'Cônjuge ou companheiro; filho de imigrante com AR; quem tem filho brasileiro ou imigrante com AR; ascendente, descendente até 2º grau ou irmão de brasileiro ou de imigrante com AR; quem tem brasileiro sob tutela ou guarda (Lei 13.445, art. 37)', 'Formulário eletrônico no site da PF + atendimento presencial (S03, S04)', 'R$ 168,13 + R$ 204,77 quando aplicáveis (S04); isenção por hipossuficiência (S08)', '130 a 180 dias corridos (estimativa geral da página do MJSP)', 'Lei nº 13.445/2017, art. 37; Decreto nº 9.199/2017; portaria vinculada pelo MJSP: Portaria Interministerial nº 3/2018 (a confirmar)', array['S14','S04','S08']::text[], 'Confirmado no MJSP (S04); página da PF restrita', 'A página da PF (S12) exigia login em 28/10/2026. Lista de documentos vem do MJSP (S04).', '28/10/2026'),
  ('P-REG-CRNM', 'Registro migratório e emissão da CRNM', 'Federal', 'Polícia Federal', 'Imigrantes com visto temporário ou com autorização de residência publicada no DOU; refugiados, apátridas e asilados reconhecidos', 'Formulário online + GRU; agendamento; atendimento na PF da circunscrição; retirada da CRNM', 'Taxa de emissão da CRNM R$ 204,77 (STN 140120); demais etapas sem custo', 'Registrar em 90 dias após a entrada (visto temporário) ou 30 dias após a publicação no DOU (AR). CRNM pronta em média em 30 dias úteis; total até 180 dias', 'Decreto nº 9.199/2017 (penalidade: art. 307, IV, segundo a FAQ da PF – S08)', array['S02','S08']::text[], 'Confirmado (etapas, prazos e taxa); lista de documentos a confirmar', 'A lista de documentos fica em página da PF que exige login.', '28/10/2026'),
  ('P-REFUGIO', 'Solicitação de refúgio (primeira vez)', 'Federal', 'MJSP / Conare + Polícia Federal', 'Pessoas estrangeiras ou apátridas com fundado temor de perseguição (raça, religião, nacionalidade, grupo social, opinião política) ou que deixaram o país por grave e generalizada violação de direitos humanos', 'Sisconare (cadastro e solicitação) + agendamento na PF + comparecimento presencial', 'Gratuito', 'Protocolo de Refúgio válido por 1 ano, renovado na PF até a decisão do Conare. Prazo total estimado: 12 a 24 meses', 'Lei nº 9.474/1997', array['S05','S06']::text[], 'Confirmado', 'Consultar o Sisconare ao menos a cada 30 dias. Cada pessoa da família precisa de agendamento próprio.', '28/10/2026'),
  ('P-DPRNM', 'Documento Provisório de Registro Nacional Migratório (DPRNM)', 'Federal', 'Polícia Federal', 'Imigrantes que estão pedindo ou renovando o refúgio', 'Atendimento na PF agendado em ''Solicitar Refúgio'' ou ''Renovar Protocolo de Refúgio''', 'Gratuito', 'Até 20 dias corridos para ficar pronto', 'A confirmar', array['S07']::text[], 'Confirmado', null, '28/10/2026'),
  ('P-ENDERECO', 'Alteração de endereço no registro migratório', 'Federal', 'Polícia Federal', 'Imigrante registrado que mudou de endereço', 'Formulário eletrônico no site da PF, sem ir à unidade', 'Gratuito', null, 'A confirmar', array['S08']::text[], 'Confirmado', null, '28/10/2026'),
  ('P-COMPROVANTE', 'Orientação: comprovante de residência e CEP', 'Varia por órgão', 'Depende do serviço de destino', 'Qualquer pessoa', 'Não é um procedimento: orientação para obter e conferir documentos', null, null, 'Não há lista universal', array['S08','S22']::text[], 'Orientação', 'Ter CEP não é ter comprovante. Cada órgão define o que aceita.', '28/10/2026');
