insert into kb_explanations (id, topic, text, status, confirmed, source_ids, note) values
  ('E01', 'O que é o CPF', 'É o número do Cadastro de Pessoas Físicas, da Receita Federal. Brasileiros e estrangeiros podem pedir, morando ou não no Brasil.', 'Confirmado', true, array['S01']::text[], null),
  ('E02', 'Quanto custa o CPF', 'É gratuito na Receita Federal, pela internet, por e-mail ou presencialmente. Nos Correios, Banco do Brasil, Caixa e cartórios custa R$ 7,00.', 'Confirmado', true, array['S01']::text[], null),
  ('E03', 'O que o CPF não faz', 'O CPF é um cadastro da Receita Federal. Ele não substitui a autorização de residência nem o registro na Polícia Federal.', 'Confirmado', true, array['S01','S03']::text[], 'Inferência a partir da natureza do cadastro; o revisor jurídico deve validar a redação'),
  ('E04', 'Onde o CPF é pedido: Carteira de Trabalho Digital', 'Para ter a Carteira de Trabalho Digital, você precisa do número do CPF e de uma conta gov.br.', 'Confirmado', true, array['S23']::text[], null),
  ('E05', 'Onde o CPF é pedido: conta em banco', null, 'A confirmar', false, array[]::text[], 'Não encontramos fonte oficial clara para estrangeiros. O app não mostra este item até confirmar.'),
  ('E06', 'Onde o CPF é pedido: linha de celular', null, 'A confirmar', false, array[]::text[], 'Regra da Anatel para estrangeiros a confirmar. O app não mostra este item até confirmar.');
